  .daily-challenge { flex-direction: column; align-items: flex-start; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }

  .tags-scroll { gap: 6px; }
  .tag-pill { padding: 6px 12px; font-size: 0.8rem; }
}

